+
+// Requests the service to force stop a job.
+message StopJobRequest {
+    // The ID of the job to kill.
+    optional int64 id = 1;
+}
+
+// The response to stopping a job.
+message StopJobResponse {}
+
+// Requests the current status of a job.
+message GetStatusRequest {
+    // The ID of the job.
+    optional int64 id = 1;
+}
+
+// A response containing a job's status.
+message GetStatusResponse {
+    enum JobStatus {
+        // The job is still running.
+        RUNNING = 0;
+        // The job has finished with exit code 0.
+        DONE = 1;
+        // The job has finished with nonzero exit code.
+        ERROR = 2;
+        // The job was killed by the user.
+        KILLED = 3;
+    }
+    // The status of the requested job.
+    optional JobStatus status = 1;
+    // This is only populated when status == ERROR
+    optional int32 exit_code = 2;
+}
+
+// A request to stream all the output generated by a job.
+message GetOutputRequest {
+    // The ID of the job.
+    optional int64 id = 1;
+    enum OutputType {
+        STDOUT = 0;
+        STDERR = 1;
+    }
+    // The output stream to read.
+    optional OutputType type = 2;
+}
+
+// A response containing one line of output. Note that this is a streaming response.
+message GetOutputResponse {
+    // A chunk of the output. While there is a guarantee that the output is streamed
+    // in order, there is no guarantee on the splitting of the output across RPCs.
+    optional string output_line = 1;

